// Verify the HMAC signature Convex puts on every request-status event,
// reject stale timestamps, and drop events this workflow already handled.
// Secret comes from the container env, never from the workflow JSON.
const crypto = require('crypto');
const SECRET = $env.HMAC_SECRET_CONVEX_TO_N8N;
const MAX_SKEW_SECONDS = 300;

if (!SECRET) throw new Error('HMAC_SECRET_CONVEX_TO_N8N is not set on the n8n container');

const item = $input.first();
const headers = item.json.headers || {};

// The signature covers the exact bytes Convex sent, so read the raw body.
let raw;
if (item.binary && item.binary.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} else {
  raw = JSON.stringify(item.json.body ?? {});
}

const result = (verdict, reason, event) => [{ json: { verdict, reason, event } }];

const timestamp = headers['x-lendloop-timestamp'];
const signature = String(headers['x-lendloop-signature'] || '');
const now = Math.floor(Date.now() / 1000);
if (!timestamp || !/^\d+$/.test(timestamp) || Math.abs(now - Number(timestamp)) > MAX_SKEW_SECONDS) {
  return result('invalid', 'missing or stale timestamp');
}

const expected =
  'sha256=' + crypto.createHmac('sha256', SECRET).update(`${timestamp}.${raw}`).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(signature);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  return result('invalid', 'signature mismatch');
}

let event;
try {
  event = JSON.parse(raw);
} catch {
  return result('invalid', 'body is not JSON');
}
if (!event.eventId || !event.recipient || !event.recipient.email) {
  return result('invalid', 'missing required fields');
}

// Convex retries if our 2xx gets lost; remember recent event ids so a retry
// never sends a second email.
const store = $getWorkflowStaticData('global');
store.seenEventIds = store.seenEventIds || [];
if (store.seenEventIds.includes(event.eventId)) {
  return result('duplicate', 'already processed', { eventId: event.eventId });
}
store.seenEventIds.push(event.eventId);
if (store.seenEventIds.length > 500) store.seenEventIds = store.seenEventIds.slice(-500);

return result('ok', null, event);

// Turn a verified request-status event into an email. Only the fields
// Convex sent are used: first names, tool name, dates, one address.
const event = $input.first().json.event;
const appUrl = $env.LENDLOOP_APP_URL || 'http://localhost:3000';
const from = { Email: $env.LENDLOOP_MAIL_FROM || 'notifications@lendloop.local', Name: 'LendLoop' };

const fmt = (iso) =>
  new Date(`${iso}T00:00:00Z`).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });
const dates =
  event.loan.startDate === event.loan.endDate
    ? fmt(event.loan.startDate)
    : `${fmt(event.loan.startDate)} to ${fmt(event.loan.endDate)}`;
const tool = event.tool.name;
const other = event.counterpart.firstName;
const reason = event.reason ? ` (${event.reason})` : '';

const templates = {
  'request.created': [
    `${other} would like to borrow your ${tool}`,
    `${other} asked to borrow your ${tool} for ${dates}.\n\nApprove or decline: ${appUrl}/incoming`,
  ],
  'request.cancelled': [
    `${other} withdrew their request for your ${tool}`,
    `${other} no longer needs your ${tool} for ${dates}. Nothing to do.`,
  ],
  'request.approved': [
    `You can borrow the ${tool}`,
    `${other} approved your request for the ${tool} (${dates}).\n\nTheir contact details are now on your request: ${appUrl}/requests`,
  ],
  'request.declined': [
    `Your request for the ${tool} was declined`,
    `Your request for the ${tool} (${dates}) was declined${reason}.\n\nOther tools: ${appUrl}/browse`,
  ],
  'loan.returned': [
    `Thanks for returning the ${tool}`,
    `${other} marked the ${tool} as returned. Thanks for borrowing responsibly!`,
  ],
};

const template = templates[event.type];
if (!template) throw new Error(`Unknown event type: ${event.type}`);
const [subject, text] = template;

return [
  {
    json: {
      eventId: event.eventId,
      mail: {
        From: from,
        To: [{ Email: event.recipient.email, Name: event.recipient.firstName }],
        Subject: subject,
        Text: `Hi ${event.recipient.firstName},\n\n${text}\n\nLendLoop`,
        Tags: ['lendloop', event.type],
      },
    },
  },
];

// Tell Convex the email went out. Signed with the n8n -> Convex secret;
// Convex de-duplicates on eventId, so retries are safe.
const crypto = require('crypto');
const SECRET = $env.HMAC_SECRET_N8N_TO_CONVEX;
if (!SECRET) throw new Error('HMAC_SECRET_N8N_TO_CONVEX is not set on the n8n container');

const eventId = $('Compose email').first().json.eventId;
const body = JSON.stringify({ eventId });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature =
  'sha256=' + crypto.createHmac('sha256', SECRET).update(`${timestamp}.${body}`).digest('hex');

return [{ json: { body, timestamp, signature } }];
